import assert from 'node:assert/strict';
import { test } from 'node:test';
import { add } from '../src/math.mjs';

test('add returns the sum', () => assert.equal(add(2, 3), 5));

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { multiply } from '../src/math.mjs';

test('multiply returns the product', () => assert.equal(multiply(2, 3), 6));

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { isEven } from '../src/math.mjs';

test('isEven recognizes an even number', () => assert.equal(isEven(4), true));

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { clamp } from '../src/math.mjs';

test('clamp limits values to both bounds', () => {
  assert.equal(clamp(12, 0, 10), 10);
  assert.equal(clamp(-2, 0, 10), 0);
  assert.equal(clamp(4, 0, 10), 4);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { parseBoolean } from '../src/math.mjs';

test('parseBoolean accepts case-insensitive true', () => assert.equal(parseBoolean('TRUE'), true));

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { average } from '../src/math.mjs';

test('average returns the arithmetic mean', () => assert.equal(average(2, 4), 3));
